// 표현식 예 — 필드 칸에 그대로 씁니다
{{ $json.Subject }}                          // 현재 항목의 제목
{{ $('Digest').item.json.date }}            // 'Digest' 노드 출력의 date
{{ $now.minus({ hours: 24 }).toISO() }}     // 24시간 전 (Luxon)
{{ $json.text.slice(0, 500) }}              // 문자열 자르기

// Code 노드 — 항목 여러 개를 하나로 합치기
const lines = $input.all().map(i => i.json.Subject);
return [{ json: { count: lines.length, lines } }];

// n8n Code 노드 (JavaScript, Run Once for All Items)
// 입력: Merge(Append) 로 합쳐진 Gmail 항목 + RSS 항목
// 출력: LLM 에 넘길 digest 문자열 하나 (항목 1개)
const MAX_BODY = 500;      // 메일 한 통에서 쓸 최대 글자 수
const MAX_MAILS = 30;      // 토큰 비용을 막는 상한

const mails = [];
const feeds = [];

for (const { json: j } of $input.all()) {
  if (j.link && j.title && !j.threadId) {
    // RSS 항목: title · link · contentSnippet
    const snippet = (j.contentSnippet || '').replace(/\s+/g, ' ').slice(0, 300);
    feeds.push(`- ${j.title} (${j.link})\n  ${snippet}`);
  } else {
    // Gmail(Simplify 켬) 항목: From · Subject · snippet
    // 필드 이름은 실행 기록(Executions)에서 한 번 확인하세요
    const from = j.From || j.from || '';
    const subject = j.Subject || j.subject || '(제목 없음)';
    const body = (j.snippet || j.text || '').replace(/\s+/g, ' ').slice(0, MAX_BODY);
    mails.push(`- [${from}] ${subject}\n  ${body}`);
  }
}

const digest = [
  `## 받은 메일 ${mails.length}건`,
  ...mails.slice(0, MAX_MAILS),
  '',
  `## RSS 새 글 ${feeds.length}건`,
  ...feeds,
].join('\n');

return [{
  json: {
    date: $now.toFormat('yyyy-MM-dd'),
    mailCount: mails.length,
    feedCount: feeds.length,
    digest,
  },
}];

[⑦ Gmail — Operation: Send]
To:       나 또는 팀 메일
Subject:  [아침 브리핑] {{ $('Digest').item.json.date }}
Email Type: Text
Message:  {{ $json.text }}
          ↑ Basic LLM Chain 의 출력 필드 이름은 실행 기록에서 확인 (보통 text)
Options › Append n8n Attribution: 끔

[⑧ Google Sheets — Operation: Append Row]
Document: 'AI 브리핑 기록' 스프레드시트 (첫 행에 date, mails, feeds, summary 헤더)
Sheet:    Sheet1
Mapping Column Mode: Map Each Column Manually
  date    = {{ $('Digest').item.json.date }}
  mails   = {{ $('Digest').item.json.mailCount }}
  feeds   = {{ $('Digest').item.json.feedCount }}
  summary = {{ $json.text.slice(0, 500) }}

[⑦ 대신 메신저로 보내려면]
Slack: Send Message / Telegram: Send Message — 본문 표현식은 같습니다.

// 정보계 아침 브리핑 — 배치 결과 메일 집계 (Code 노드, Run Once for All Items)
// 가정: 배치 서버가 보내는 메일 제목 형식
//   [BATCH][OK]   DW_DAILY_LOAD  02:14~02:51
//   [BATCH][FAIL] ODS_CUST_SNAP  03:05  ORA-01652
//   [BATCH][LATE] STG_ACCT_HIST  예정 04:00 → 05:12
const RE = /\[BATCH\]\[(OK|FAIL|LATE)\]\s+(\S+)\s*(.*)/;

const counts = { OK: 0, FAIL: 0, LATE: 0 };
const issues = [];
const unknown = [];

for (const { json: j } of $input.all()) {
  const subject = j.Subject || j.subject || '';
  const m = subject.match(RE);
  if (!m) { unknown.push(subject); continue; }
  const [, status, job, rest] = m;
  counts[status] += 1;
  if (status !== 'OK') {
    issues.push({
      status, job, detail: rest.trim(),
      body: (j.snippet || '').replace(/\s+/g, ' ').slice(0, 400),
    });
  }
}

return [{
  json: {
    date: $now.toFormat('yyyy-MM-dd'),
    okCount: counts.OK,
    failCount: counts.FAIL,
    lateCount: counts.LATE,
    issues,                       // LLM 에는 실패·지연 건만 넘깁니다
    unknownSubjects: unknown,     // 형식이 다른 메일은 따로 표시
    oneLine: `정상 ${counts.OK} · 실패 ${counts.FAIL} · 지연 ${counts.LATE}`,
  },
}];

package study.s05;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.List;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

/** n8n 의 ② Gmail · ③ RSS Read 노드 대신: 메일과 RSS 항목을 읽어 옵니다. */
public final class Inbox {

    /** Gmail 노드(Simplify 켬) 출력과 같은 필드 */
    @JsonIgnoreProperties(ignoreUnknown = true)
    public record Mail(String from, String subject, String snippet, String received, String category) {}

    public record FeedItem(String title, String link, String summary) {}

    private static final ObjectMapper JSON = new ObjectMapper();

    private Inbox() {}

    /** 지난 24시간에 받은 메일, 프로모션 제외 (n8n 의 Received After · -category:promotions). */
    public static List<Mail> mails(Path file, OffsetDateTime at) throws IOException {
        List<Mail> all = JSON.readValue(file.toFile(), new TypeReference<List<Mail>>() {});
        OffsetDateTime since = at.minusHours(24);
        return all.stream()
                .filter(m -> !"promotions".equals(m.category()))
                .filter(m -> {
                    OffsetDateTime t = OffsetDateTime.parse(m.received());
                    return !t.isBefore(since) && !t.isAfter(at);
                })
                .toList();
    }

    /** RSS 2.0 을 JDK 내장 XML 파서로 읽습니다. 주소(http…)와 파일 경로를 모두 받습니다. Atom 까지 다뤄야 하면 Rome 라이브러리를 씁니다. */
    public static List<FeedItem> feed(String source) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);   // 외부 엔터티(XXE) 차단
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = source.startsWith("http") ? builder.parse(source) : builder.parse(new File(source));

        List<FeedItem> items = new ArrayList<>();
        NodeList nodes = doc.getElementsByTagName("item");
        for (int i = 0; i < nodes.getLength(); i++) {
            Element e = (Element) nodes.item(i);
            items.add(new FeedItem(child(e, "title"), child(e, "link"), child(e, "description")));
        }
        return items;
    }

    private static String child(Element e, String tag) {
        NodeList n = e.getElementsByTagName(tag);
        return n.getLength() == 0 ? "" : n.item(0).getTextContent().strip();
    }
}

package study.s05;

import java.nio.file.Path;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * n8n 의 ④ Merge + ⑤ Code(Digest) 노드: 메일 · RSS 항목 수십 개를 문자열 하나로 합쳐 LLM 호출을 한 번으로 줄입니다.
 * ./mvnw -q compile exec:java -Dexec.mainClass=study.s05.Digest   (이 단계만 실행해 결과 확인)
 */
public record Digest(String date, int mailCount, int feedCount, String digest) {
    static final ZoneId KST = ZoneId.of("Asia/Seoul");
    static final int MAX_BODY = 500;    // 메일 한 통에서 쓸 최대 글자 수
    static final int MAX_MAILS = 30;    // 토큰 비용을 막는 상한
    static final Path DATA = Path.of(System.getProperty("data", "../python/data"));   // Python 트랙과 같은 샘플
    static final String FEED = System.getProperty("feed", DATA.resolve("feed.xml").toString());

    /** -Dnow=2026-11-13T07:30:00+09:00 이 있으면 그 시각, 없으면 지금(서울 시간). */
    static OffsetDateTime now() {
        String v = System.getProperty("now", System.getenv("BRIEF_NOW"));
        return v != null ? OffsetDateTime.parse(v) : OffsetDateTime.now(KST);
    }

    /** HTML 태그와 연속 공백을 지우고 limit 글자로 자릅니다. */
    static String squash(String text, int limit) {
        String s = (text == null ? "" : text).replaceAll("<[^>]+>", " ").replaceAll("\\s+", " ").strip();
        return s.length() <= limit ? s : s.substring(0, limit);
    }

    public static Digest build(OffsetDateTime at) throws Exception {
        List<String> mails = new ArrayList<>();
        for (Inbox.Mail m : Inbox.mails(DATA.resolve("mails.json"), at)) {
            String subject = m.subject() == null || m.subject().isEmpty() ? "(제목 없음)" : m.subject();
            mails.add("- [" + m.from() + "] " + subject + "\n  " + squash(m.snippet(), MAX_BODY));
        }
        List<String> feeds = new ArrayList<>();
        for (Inbox.FeedItem f : Inbox.feed(FEED)) {
            feeds.add("- " + f.title() + " (" + f.link() + ")\n  " + squash(f.summary(), 300));
        }
        List<String> lines = new ArrayList<>();
        lines.add("## 받은 메일 " + mails.size() + "건");
        lines.addAll(mails.subList(0, Math.min(MAX_MAILS, mails.size())));
        lines.add("");
        lines.add("## RSS 새 글 " + feeds.size() + "건");
        lines.addAll(feeds);
        String date = at.atZoneSameInstant(KST).format(DateTimeFormatter.ISO_LOCAL_DATE);
        return new Digest(date, mails.size(), feeds.size(), String.join("\n", lines));
    }

    public static void main(String[] args) throws Exception {
        Digest d = build(now());
        System.out.printf("%s 메일 %d건 · RSS %d건%n%n%s%n", d.date(), d.mailCount(), d.feedCount(), d.digest());
    }
}

package study.s05;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.TextBlock;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * 아침 브리핑: digest → Claude 요약 → 파일 저장 · CSV 기록.
 * n8n 의 ⑥ Basic LLM Chain ⑦ Gmail Send ⑧ Google Sheets Append 를 코드로 옮긴 것입니다.
 * ./mvnw -q compile exec:java -Dexec.mainClass=study.s05.Briefing -Dnow=2026-11-13T07:30:00+09:00
 */
public class Briefing {
    // 요약은 claude-haiku-5-5 로도 충분한지 비교해 보세요
    static final String MODEL = System.getenv().getOrDefault("CLAUDE_MODEL", "claude-sonnet-5-5");
    static final Path OUT = Path.of(System.getProperty("out", "out"));

    // n8n 실습의 prompt.txt 와 같은 문구 (%s · %d 자리에 값이 들어갑니다)
    static final String PROMPT = """
            아래는 %s 아침까지 받은 메일 %d건과
            RSS 새 글 %d건입니다.

            다음 형식으로 한국어 브리핑을 작성하세요.
            1. 오늘 꼭 처리할 일 (최대 3개, 보낸 사람 표시)
            2. 참고만 할 메일 (한 줄씩)
            3. 기술 소식 (RSS, 제목과 한 줄 요약)
            - 원문에 없는 내용은 쓰지 않습니다.
            - 전체 15줄 이내.

            ---
            %s""";

    static String summarize(Digest d) {
        AnthropicClient client = AnthropicOkHttpClient.fromEnv();   // ANTHROPIC_API_KEY — 코드와 파일에는 키를 두지 않습니다
        MessageCreateParams params = MessageCreateParams.builder()
                .model(MODEL)
                .maxTokens(2048)                 // temperature · top_p 는 넣지 않습니다 (Claude 5.5 는 400 오류)
                .addUserMessage(PROMPT.formatted(d.date(), d.mailCount(), d.feedCount(), d.digest()))
                .build();
        Message msg = client.messages().create(params);
        return msg.content().stream().flatMap(b -> b.text().stream())   // thinking 블록 건너뛰기
                .map(TextBlock::text).collect(Collectors.joining()).strip();
    }

    /** CSV 한 칸: 따옴표로 감싸고 안의 따옴표는 두 번 씁니다 (쉼표 · 줄바꿈이 있어도 한 칸). */
    static String csv(Object v) {
        return "\"" + String.valueOf(v).replace("\"", "\"\"") + "\"";
    }

    /** ⑦ 대신 Markdown 파일, ⑧ 대신 CSV 한 줄. 엑셀에서 한글이 깨지지 않게 새 CSV 는 BOM 을 붙입니다. */
    static Path deliver(Digest d, String summary) throws Exception {
        Files.createDirectories(OUT);
        Path md = OUT.resolve("briefing-" + d.date() + ".md");
        Files.writeString(md, "# [아침 브리핑] " + d.date() + "\n\n" + summary + "\n", StandardCharsets.UTF_8);

        Path log = OUT.resolve("briefing_log.csv");
        String row = Stream.of(d.date(), d.mailCount(), d.feedCount(), summary.substring(0, Math.min(500, summary.length())))
                .map(Briefing::csv).collect(Collectors.joining(",")) + "\r\n";
        if (Files.notExists(log)) row = "\uFEFFdate,mails,feeds,summary\r\n" + row;
        Files.writeString(log, row, StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        return md;
    }

    public static void main(String[] args) throws Exception {
        Digest d = Digest.build(Digest.now());
        String summary = summarize(d);     // 메일 0건이어도 '메일 0건' 브리핑을 만듭니다
        Path md = deliver(d, summary);
        System.out.println(summary);
        System.out.println("\n저장: " + md + " · 기록: " + OUT.resolve("briefing_log.csv"));
    }
}
